function check([numerator, denominator], actual, expected) {
  if (typeof actual !== 'string') return false;
  const match = /^(-?)(0|[1-9][0-9]*)(?:\.([0-9]*)(?:\(([0-9]+)\))?)?$/.exec(actual);
  if (!match) return false;
  const [, minus, whole, fixed = '', cycle = ''] = match;
  if (actual.includes('.') && fixed === '' && cycle === '') return false;
  // A finite value must be written in its finite form, without trailing zeros.
  const finite = !expected.includes('(');
  if (finite && cycle !== '') return false;
  if (cycle === '' && fixed.endsWith('0')) return false;
  // whole.fixed(cycle) equals (wholefixedcycle - wholefixed) / (10^|fixed| * (10^|cycle| - 1)).
  let top = BigInt(whole + fixed);
  let bottom = 10n ** BigInt(fixed.length);
  if (cycle !== '') {
    top = BigInt(whole + fixed + cycle) - top;
    bottom *= 10n ** BigInt(cycle.length) - 1n;
  }
  if (minus && top === 0n) return false;
  if (minus) top = -top;
  return top * BigInt(denominator) === BigInt(numerator) * bottom;
}

