function validate([numerator, denominator]) {
  const MIN = -(2 ** 31), MAX = 2 ** 31 - 1;
  if (!Number.isInteger(numerator) || !Number.isInteger(denominator)) return 'Both values must be integers.';
  if (numerator < MIN || numerator > MAX || denominator < MIN || denominator > MAX) return 'Both values must fit in a 32-bit signed integer.';
  if (denominator === 0) return 'denominator must not be 0.';
  const bottom = Math.abs(denominator);
  let remainder = Math.abs(numerator) % bottom;
  let length = String(Math.floor(Math.abs(numerator) / bottom)).length + ((numerator < 0) !== (denominator < 0) && numerator !== 0 ? 1 : 0);
  if (remainder === 0) return null;
  length += 1;
  const seen = new Set();
  while (remainder !== 0 && !seen.has(remainder)) {
    seen.add(remainder);
    remainder = (remainder * 10) % bottom;
    length += 1;
    if (length >= 10000) return 'The answer must be shorter than 10^4 characters.';
  }
  if (remainder !== 0 && length + 2 >= 10000) return 'The answer must be shorter than 10^4 characters.';
  return null;
}

