function fractionToDecimal(numerator, denominator) {
  if (numerator === 0) {
    return '0';
  }
  const parts = [];
  if ((numerator < 0) !== (denominator < 0)) {
    parts.push('-');
  }
  const top = Math.abs(numerator);
  const bottom = Math.abs(denominator);
  parts.push(String(Math.floor(top / bottom)));
  let remainder = top % bottom;
  if (remainder === 0) {
    return parts.join('');
  }
  parts.push('.');
  const seen = new Map();
  while (remainder !== 0) {
    if (seen.has(remainder)) {
      parts.splice(seen.get(remainder), 0, '(');
      parts.push(')');
      return parts.join('');
    }
    seen.set(remainder, parts.length);
    remainder *= 10;
    parts.push(String(Math.floor(remainder / bottom)));
    remainder %= bottom;
  }
  return parts.join('');
}

