function fractionToDecimal(numerator, denominator) {
  let num = BigInt(numerator);
  let den = BigInt(denominator);
  const negative = num !== 0n && (num < 0n) !== (den < 0n);
  if (num < 0n) num = -num;
  if (den < 0n) den = -den;
  const gcd = (a, b) => (b === 0n ? a : gcd(b, a % b));
  const g = gcd(num, den);
  num /= g;
  den /= g;
  const whole = (negative ? '-' : '') + (num / den).toString();
  const rest = num % den;
  if (rest === 0n) return whole;
  // For a reduced fraction, the digits before the cycle come from the 2s and 5s of den,
  // and the cycle length is the order of 10 modulo what is left.
  let m = den, twos = 0, fives = 0;
  while (m % 2n === 0n) { m /= 2n; twos++; }
  while (m % 5n === 0n) { m /= 5n; fives++; }
  const pre = Math.max(twos, fives);
  let period = 0;
  if (m > 1n) {
    period = 1;
    for (let power = 10n % m; power !== 1n; power = (power * 10n) % m) period++;
  }
  const digits = ((rest * 10n ** BigInt(pre + period)) / den).toString().padStart(pre + period, '0');
  return whole + '.' + digits.slice(0, pre) + (period > 0 ? '(' + digits.slice(pre) + ')' : '');
}

