function generate(rand, size) {
  const MIN = -(2 ** 31), MAX = 2 ** 31 - 1;
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const sign = () => (rand() < 0.5 ? -1 : 1);
  const pick = (list) => list[int(0, list.length - 1)];
  // The answer must stay under 10^4 characters; count its fractional digits by long division.
  const shortEnough = (numerator, denominator) => {
    const bottom = Math.abs(denominator);
    let remainder = Math.abs(numerator) % bottom;
    const seen = new Set();
    let digits = 0;
    while (remainder !== 0 && !seen.has(remainder)) {
      seen.add(remainder);
      remainder = (remainder * 10) % bottom;
      digits++;
      if (digits > 9950) return false;
    }
    return true;
  };
  for (;;) {
    let numerator, denominator;
    const mode = rand();
    if (size === 'small') {
      numerator = int(-60, 60);
      denominator = int(-40, 40);
      if (mode < 0.1) numerator = pick([MIN, MAX, 0, -1]);
      else if (mode > 0.9) denominator = pick([MIN, MAX, -1, 1, 7, 81]);
    } else if (mode < 0.35) {
      numerator = int(MIN, MAX);
      denominator = sign() * int(1000, 9900);
    } else if (mode < 0.55) {
      const twos = int(0, 30);
      let bottom = 2 ** twos;
      while (bottom * 5 <= MAX && rand() < 0.7) bottom *= 5;
      numerator = int(MIN, MAX);
      denominator = sign() * bottom;
    } else if (mode < 0.7) {
      denominator = sign() * int(1, 46000);
      numerator = Math.abs(denominator) * int(-46000, 46000);
    } else if (mode < 0.85) {
      numerator = pick([MIN, MAX, MIN + 1, -1, 1, 0]);
      denominator = pick([MIN, MAX, -1, 1, 2, -3, 7, 97, -9999, 65536]);
    } else {
      numerator = int(MIN, MAX);
      denominator = sign() * pick([3, 6, 7, 9, 11, 12, 13, 17, 37, 41, 101, 333, 999, 1001, 7 * 1024, 3 * 78125]);
    }
    if (denominator === 0 || !shortEnough(numerator, denominator)) continue;
    return [numerator, denominator];
  }
}
